{
    public static int FinalPrice(int unitCents, int qty)
    {
        int percent = qty >= 100 ? 20 : qty >= 50 ? 10 : qty >= 10 ? 5 : 0;
        int gross = unitCents * qty;
        return gross - gross * percent / 100;
    }
}

