test_setup_files.tests/DiscountTests.cs:
using Xunit;

public class DiscountTests
{
    [Fact]
    public void QuoteDiscountTiers()
    {
        Assert.Equal(0, QuoteService.DiscountPercent(9));
        Assert.Equal(5, QuoteService.DiscountPercent(10));
        Assert.Equal(5, QuoteService.DiscountPercent(49));
        Assert.Equal(10, QuoteService.DiscountPercent(50));
        Assert.Equal(10, QuoteService.DiscountPercent(99));
        Assert.Equal(20, QuoteService.DiscountPercent(100));
    }

    [Fact]
    public void CheckoutAppliesDiscount()
    {
        Assert.Equal(900, CheckoutService.FinalPrice(100, 9));
        Assert.Equal(4500, CheckoutService.FinalPrice(100, 50));
        Assert.Equal(8000, CheckoutService.FinalPrice(100, 100));
    }

    [Fact]
    public void ServicesAgreeAtBoundaries()
    {
        Assert.Equal(10, QuoteService.DiscountPercent(50));
        Assert.Equal(20, QuoteService.DiscountPercent(100));
    }
}

